// 1. Get the raw text. 
// If the API returned a stringified JSON string (double-encoded), 
// we might need to parse it once to unwrap the outer quotes.
let content = $input.first().json.data;

if (typeof content === 'string') {
  try {
    // Try to unwrap if it's a string inside a string (e.g. "\"{\\\"a\\\":1}\"")
    // If this fails, it's just normal text, and we proceed.
    const potentialObj = JSON.parse(content);
    if (typeof potentialObj === 'string') {
      content = potentialObj;
    }
  } catch (e) {
    // It wasn't double-encoded, carry on with original content
  }
}

// 2. The "Smart" Cleanup
// Instead of replacing "```json", we just hunt for the first '{' and last '}'
// This ignores all markdown, preambles, and outer quotes automatically.
const firstBracket = content.indexOf('{');
const lastBracket = content.lastIndexOf('}');

if (firstBracket !== -1 && lastBracket !== -1) {
  const jsonString = content.substring(firstBracket, lastBracket + 1);

  try {
    const parsed = JSON.parse(jsonString);
    return { json: parsed }; 
  } catch (e) {
    return { json: { error: "Inner parsing failed", text: jsonString } };
  }
} else {
  return { json: { error: "No JSON object found", text: content } };
}

options.systemMessage:
=Create a presentation in Marp Markdown format based on the following input.



STRICT LAYOUT RULES:

1. Frontmatter: The very first lines of your response MUST be the YAML frontmatter provided below. Do not include any text, greetings, or "Sure, here is your presentation" before it.

2. Content Splitting: You MUST create a NEW SLIDE (using '---') for every distinct section or major topic.

3. "One Header" Rule: Never put two "## H2 Headers" on the same slide. If you start a new ## Header, you MUST put '---' before it.

4. Bullet Limits: Maximum 5 bullet points per slide. If there are more, split them into two slides (e.g., "Key Areas Part 1" and "Key Areas Part 2").

5. Output raw Markdown text only. Do not use markdown code blocks (```). Ensure the first line of the output is the opening '---' of the frontmatter.



---

marp: true

theme: default

paginate: true

size: 16:9

style: |

  section {

    font-size: 25px;

    padding: 40px;

    justify-content: center; /* Keeps content centered vertically */

  }

  h1 {

    font-size: 50px;

    color: #0288d1;

  }

  h2 {

    font-size: 35px;

    color: #333;

  }

---



Input Data: {{ $json.data }}

