const lesson_id = $('prepare').first().json._id
for (let i = 0; i < $('Code in JavaScript').first().json.script.length; i++) {
  const url =`https://capstone-ai-education.s3.amazonaws.com/${lesson_id}/audio/audio_${i}.wav`
  audioURLs.push(url)
}

return { 
  audioURLs, 
  "_id": lesson_id,
  audioStatus: "GENERATED"
};

